#include <gmp.h>
#include <gmpxx.h>
#include <bits/stdc++.h>
#ifdef _OPENMP
#include <omp.h>
#endif
using namespace std;
extern "C" {
typedef long mpfr_prec_t; typedef int mpfr_sign_t; typedef long mpfr_exp_t; typedef enum{MPFR_RNDN=0,MPFR_RNDZ=1,MPFR_RNDU=2,MPFR_RNDD=3,MPFR_RNDA=4,MPFR_RNDF=5} mpfr_rnd_t; typedef struct{mpfr_prec_t _mpfr_prec;mpfr_sign_t _mpfr_sign;mpfr_exp_t _mpfr_exp;mp_limb_t*_mpfr_d;} __mpfr_struct; typedef __mpfr_struct mpfr_t[1]; typedef __mpfr_struct* mpfr_ptr; typedef const __mpfr_struct* mpfr_srcptr;
void mpfr_init2(mpfr_ptr,mpfr_prec_t); void mpfr_clear(mpfr_ptr); int mpfr_set_q(mpfr_ptr,mpq_srcptr,mpfr_rnd_t); int mpfr_set_ui(mpfr_ptr,unsigned long,mpfr_rnd_t); int mpfr_set(mpfr_ptr,mpfr_srcptr,mpfr_rnd_t); int mpfr_log(mpfr_ptr,mpfr_srcptr,mpfr_rnd_t); int mpfr_neg(mpfr_ptr,mpfr_srcptr,mpfr_rnd_t); int mpfr_add(mpfr_ptr,mpfr_srcptr,mpfr_srcptr,mpfr_rnd_t); int mpfr_sub(mpfr_ptr,mpfr_srcptr,mpfr_srcptr,mpfr_rnd_t); int mpfr_mul(mpfr_ptr,mpfr_srcptr,mpfr_srcptr,mpfr_rnd_t); int mpfr_div_ui(mpfr_ptr,mpfr_srcptr,unsigned long,mpfr_rnd_t); int mpfr_cmp_si(mpfr_srcptr,long); double mpfr_get_d(mpfr_srcptr,mpfr_rnd_t);
}
static constexpr mpfr_prec_t PREC=128; static constexpr int DEG=7; static const int BIN[8]={1,7,21,35,35,21,7,1};
static mpq_class Q(long n,long d=1){mpq_class q(n,d);q.canonicalize();return q;}
struct MP{mpfr_t v;MP(){mpfr_init2(v,PREC);mpfr_set_ui(v,0,MPFR_RNDN);}~MP(){mpfr_clear(v);}MP(const MP&)=delete;};
static void setq(MP&x,const mpq_class&q,mpfr_rnd_t r){mpfr_set_q(x.v,q.get_mpq_t(),r);}static double getd(const MP&x){return mpfr_get_d(x.v,MPFR_RNDN);} 
static void neglog_bounds(const mpq_class&q,MP&lo,MP&hi){MP qlo,qhi,lgu,lgd;setq(qlo,q,MPFR_RNDD);setq(qhi,q,MPFR_RNDU);mpfr_log(lgu.v,qhi.v,MPFR_RNDU);mpfr_neg(lo.v,lgu.v,MPFR_RNDD);mpfr_log(lgd.v,qlo.v,MPFR_RNDD);mpfr_neg(hi.v,lgd.v,MPFR_RNDU);} 
static void entropy_bounds(const mpq_class&q,MP&lo,MP&hi){if(q==0||q==1){mpfr_set_ui(lo.v,0,MPFR_RNDN);mpfr_set_ui(hi.v,0,MPFR_RNDN);return;}mpq_class r=1-q;MP qlo,qhi,rlo,rhi,a,b,c,d,t1l,t1h,t2l,t2h;setq(qlo,q,MPFR_RNDD);setq(qhi,q,MPFR_RNDU);setq(rlo,r,MPFR_RNDD);setq(rhi,r,MPFR_RNDU);neglog_bounds(q,a,b);neglog_bounds(r,c,d);mpfr_mul(t1l.v,qlo.v,a.v,MPFR_RNDD);mpfr_mul(t1h.v,qhi.v,b.v,MPFR_RNDU);mpfr_mul(t2l.v,rlo.v,c.v,MPFR_RNDD);mpfr_mul(t2h.v,rhi.v,d.v,MPFR_RNDU);mpfr_add(lo.v,t1l.v,t2l.v,MPFR_RNDD);mpfr_add(hi.v,t1h.v,t2h.v,MPFR_RNDU);} 
struct Mask{uint64_t lo,hi;};static inline bool bit(const Mask&m,int x){return x<64?((m.lo>>x)&1):((m.hi>>(x-64))&1);} static inline int pc(const Mask&m){return __builtin_popcountll(m.lo)+__builtin_popcountll(m.hi);} 
using Poly=array<mpq_class,8>; struct Group{Poly p;int mult;};
static pair<Poly,Poly> split_half(const Poly&c){mpq_class row[8][8];for(int i=0;i<8;i++)row[0][i]=c[i];for(int r=1;r<8;r++)for(int i=0;i<8-r;i++)row[r][i]=(row[r-1][i]+row[r-1][i+1])/2;Poly L,R;for(int i=0;i<8;i++){L[i]=row[i][0];R[i]=row[7-i][i];}return {L,R};}
static pair<Poly,Poly> subdiv(const Poly&c,const mpq_class&t){mpq_class row[8][8];for(int i=0;i<8;i++)row[0][i]=c[i];for(int r=1;r<8;r++)for(int i=0;i<8-r;i++)row[r][i]=(1-t)*row[r-1][i]+t*row[r-1][i+1];Poly L,R;for(int i=0;i<8;i++){L[i]=row[i][0];R[i]=row[7-i][i];}return {L,R};}
static Poly restrictp(const Poly&c,const mpq_class&a,const mpq_class&b){Poly L=c;if(b!=1)L=subdiv(c,b).first;if(a==0)return L;return subdiv(L,a/b).second;}
static vector<Group> groups(const Mask&m){map<array<unsigned char,8>,int>mp;for(int y=0;y<128;y++){array<unsigned char,8>c{};for(int x=0;x<128;x++)if(bit(m,x))c[__builtin_popcount((unsigned)(x^y))]++;mp[c]++;}vector<Group>v;v.reserve(mp.size());for(auto&kv:mp){Group g;g.mult=kv.second;for(int d=0;d<8;d++)g.p[d]=Q(kv.first[d],BIN[d]);v.push_back(move(g));}return v;}
static bool isdict(const Mask&m){for(int i=0;i<7;i++)for(int inv=0;inv<2;inv++){bool ok=1;for(int x=0;x<128;x++)if(bit(m,x)!=bool(((x>>i)&1)^inv)){ok=0;break;}if(ok)return 1;}return 0;}
struct Stats{long long nodes=0,leaves=0;int maxd=0;double minlb=1e99;};
static bool interval_lower(const vector<Group>&gs,const mpq_class&b,const MP&ln2lo,const MP&hpU,double&out){MP hbL,hbU,sumL,dlo;entropy_bounds(b,hbL,hbU);mpfr_set(dlo.v,ln2lo.v,MPFR_RNDD);mpfr_sub(dlo.v,dlo.v,hbU.v,MPFR_RNDD);mpfr_sub(dlo.v,dlo.v,hpU.v,MPFR_RNDD);mpfr_set_ui(sumL.v,0,MPFR_RNDN);for(auto&g:gs){mpq_class lo=g.p[0],hi=g.p[0];for(int i=1;i<8;i++){if(g.p[i]<lo)lo=g.p[i];if(g.p[i]>hi)hi=g.p[i];}mpq_class q=(abs(2*lo-1)>=abs(2*hi-1)?lo:hi);MP hL,hU;entropy_bounds(q,hL,hU);for(int k=0;k<g.mult;k++)mpfr_add(sumL.v,sumL.v,hL.v,MPFR_RNDD);}mpfr_div_ui(sumL.v,sumL.v,128,MPFR_RNDD);mpfr_add(dlo.v,dlo.v,sumL.v,MPFR_RNDD);out=getd(dlo);return mpfr_cmp_si(dlo.v,0)>0;}
static bool cert(vector<Group>gs,mpq_class a,mpq_class b,const MP&ln2lo,const MP&hpU,int dep,Stats&st){st.nodes++;st.maxd=max(st.maxd,dep);double lb; if(interval_lower(gs,b,ln2lo,hpU,lb)){st.leaves++;st.minlb=min(st.minlb,lb);return true;} if(dep>=34)return false;vector<Group>L,R;L.reserve(gs.size());R.reserve(gs.size());for(auto&g:gs){auto z=split_half(g.p);L.push_back({move(z.first),g.mult});R.push_back({move(z.second),g.mult});}mpq_class mid=(a+b)/2;bool x=cert(move(L),a,mid,ln2lo,hpU,dep+1,st);if(!x)return false;return cert(move(R),mid,b,ln2lo,hpU,dep+1,st);}
int main(int argc,char**argv){ifstream in("/tmp/s7_reps.txt");string s;vector<Mask>ms;while(in>>s)ms.push_back({stoull(s.substr(16),0,16),stoull(s.substr(0,16),0,16)});int start=argc>1?atoi(argv[1]):0,lim=argc>2?atoi(argv[2]):100;int end=min((int)ms.size(),start+lim);MP ln2lo,ln2hi; mpq_class half=Q(1,2); entropy_bounds(half,ln2lo,ln2hi);mpq_class a=Q(1,5000),b=Q(67,135);auto t0=chrono::steady_clock::now();for(int idx=start;idx<end;idx++){auto&m=ms[idx];int k=pc(m);if(k==0||k==128||isdict(m))continue;vector<Group>gs=groups(m);for(auto&g:gs)g.p=restrictp(g.p,a,b);MP hpL,hpU;entropy_bounds(Q(k,128),hpL,hpU);Stats st;bool ok=cert(move(gs),a,b,ln2lo,hpU,0,st);if(!ok){cerr<<"FAIL idx="<<idx<<" k="<<k<<" nodes="<<st.nodes<<" maxd="<<st.maxd<<"\n";return 2;}if((idx-start+1)%10==0)cerr<<"done "<<idx+1<<" nodes="<<st.nodes<<" maxd="<<st.maxd<<" sec="<<chrono::duration<double>(chrono::steady_clock::now()-t0).count()<<"\n";}cerr<<"PASS range "<<start<<" "<<end<<" sec="<<chrono::duration<double>(chrono::steady_clock::now()-t0).count()<<"\n";}
